#pragma once
#include <string>
#include <vector>
#include <sstream>
#include <iomanip>

namespace indicators {

class Format {
public:
    static std::string percentage(float value, int precision = 1) {
        std::ostringstream oss;
        oss << std::fixed << std::setprecision(precision) << (value * 100.0f) << "%";
        return oss.str();
    }
};

class ProgressBuilder {
public:
    ProgressBuilder& set_progress(int v) { progress_ = v; return *this; }
    ProgressBuilder& set_total(int v)    { total_ = v;    return *this; }
    std::string build() const {
        return Format::percentage(static_cast<float>(progress_) / static_cast<float>(total_));
    }
private:
    int progress_ = 0;
    int total_ = 100;
};

class ProgressTracker {
public:
    ProgressTracker& add_stage(const std::string& name) { stages_.push_back(name); return *this; }
    void set_progress(int v) { progress_ = v; }
    void set_total(int v)    { total_ = v; }
    std::string get_progress() const {
        std::ostringstream oss;
        oss << progress_ << "/" << total_;
        return oss.str();
    }
    std::string get_percentage() const {
        return Format::percentage(static_cast<float>(progress_) / static_cast<float>(total_));
    }
private:
    int progress_ = 0;
    int total_ = 100;
    std::vector<std::string> stages_;
};

}
EOF
